const pageSize=20,statusName={deleting:'删除中',running:'运行中',starting:'启动中',provisioning:'创建中',stopped:'已休眠',stopping:'休眠中',error:'异常'},roleName=r=>({platform_admin:'平台管理员',tenant_admin:'租户管理员',member:'普通用户'})[r]||r,accessName={owner:'负责人',operator:'运维者',member:'成员'}
