async function loadAdminAudit(offset=0){adminAuditOffset=Math.max(offset,0);const r=await request(`/api/admin/audit-logs?limit=${adminAuditPageSize}&offset=${adminAuditOffset}`);$('#audit-table').innerHTML=r.logs.length?'<div class="row head"><span>时间</span><span>操作</span><span>目标</span></div>'+r.logs.map(x=>`<div class="row"><span>${new Date(x.createdAt).toLocaleString()}</span><span>${esc(x.actor)} · ${esc(actionNames[x.action]||x.action)}</span><span>${esc(x.targetInstance||'')} ${esc(x.targetUser||'')}</span></div>`).join(''):'<div class="empty compact">暂无管理员操作记录。</div>';$('#admin-audit-page').textContent=`${Math.floor(adminAuditOffset/adminAuditPageSize)+1} / ${Math.max(Math.ceil(r.total/adminAuditPageSize),1)} 页 · 共 ${r.total} 条`;$('#admin-audit-prev').disabled=!adminAuditOffset;$('#admin-audit-next').disabled=adminAuditOffset+adminAuditPageSize>=r.total}
async function loadOverview(){if(me.role!=='platform_admin')return;const tenantFilter=$('#user-tenant-filter').value;overview=await request('/api/admin/overview?metadataOnly=true');const opts=overview.tenants.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('#user-form select[name=tenantId]').innerHTML=opts;$('#instance-form select[name=tenantId]').innerHTML=opts;$('#user-tenant-filter').innerHTML='<option value="all">全部租户</option>'+opts;$('#user-tenant-filter').value=overview.tenants.some(x=>x.id===tenantFilter)?tenantFilter:'all';$('#dsh-version-select').innerHTML=(overview.versions||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.id)}</option>`).join('');$('#user-status-filter').options[1].value='true';$('#user-status-filter').options[2].value='false';summary('#identity-summary',[['用户总数',overview.summary.total,'平台身份'],['已启用',overview.summary.enabled,'可正常登录'],['租户数',overview.tenants.length,'组织边界'],['管理员',overview.summary.admins,'平台与租户管理员']]);await loadUsers();renderTenants()}
function renderUsers(){const users=overview.users;$('#user-table').innerHTML='<div class="row user-row head"><span>用户</span><span>所属租户</span><span>角色</span><span>状态</span><span>操作</span></div>'+(users.length?users.map(x=>`<div class="row user-row"><span><strong>${esc(x.displayName)}</strong><small>${esc(x.username)}</small></span><span>${esc(x.tenantName||'-')}</span><span class="pill">${esc(roleName(x.role))}</span><span class="pill ${x.enabled?'':'disabled'}">${x.enabled?'已启用':'已停用'}</span><span class="row-actions"><button class="user-audit" data-id="${x.id}">审计</button>${x.role==='platform_admin'?'':`<button class="user-edit" data-id="${x.id}">编辑</button><button class="user-password" data-id="${x.id}">初始化密码</button>`}</span></div>`).join(''):'<div class="empty compact">没有符合条件的用户。</div>');bindUsers();renderPager('users',userPage,userPageSize,userTotal)}
function renderTenants(){$('#tenant-table').innerHTML='<div class="row tenant-row head"><span>租户</span><span>编码</span><span>成员 / 空间</span><span>操作</span></div>'+overview.tenants.map(x=>`<div class="row tenant-row"><strong>${esc(x.name)}</strong><span>${esc(x.code)}</span><span>${x.memberCount||0} / ${x.spaceCount||0}</span><span class="row-actions"><button class="tenant-edit" data-id="${x.id}">管理</button></span></div>`).join('');$$('.tenant-edit').forEach(b=>b.onclick=()=>openTenant(b.dataset.id))}
function openTenant(id){const tenant=overview.tenants.find(x=>x.id===id),f=$('#edit-tenant-form');if(!tenant)return;f.dataset.id=id;f.elements.name.value=tenant.name;f.elements.code.value=tenant.code;f.elements.code.readOnly=tenant.code==='default';f.querySelector('.form-message').textContent='';$('#tenant-delete').disabled=tenant.code==='default';$('#edit-tenant-dialog').showModal()}
