const modelSyncName={unmanaged:'尚未由平台管理',pending:'待同步（容器就绪后自动同步）',synced:'已同步',error:'同步失败，请检查空间镜像、状态与凭证后重试'}
async function loadModelProviders(){if(me.role!=='platform_admin')return;try{modelProviders=(await request('/api/admin/model-providers')).providers;renderModelProviders()}catch(error){toast(error.message,'error')}}
function renderModelProviders(){const q=$('#model-search').value.trim().toLowerCase(),items=modelProviders.filter(p=>!q||`${p.name} ${p.code} ${p.config.models.map(m=>m.id).join(' ')}`.toLowerCase().includes(q));summary('#model-summary',[['提供方',modelProviders.length,'平台登记'],['已启用',modelProviders.filter(p=>p.enabled).length,'可供空间接入'],['模型',modelProviders.reduce((n,p)=>n+p.config.models.length,0),'已登记目录'],['空间接入',modelProviders.reduce((n,p)=>n+p.spaceCount,0),'绑定关系']]);$('#model-table').innerHTML='<div class="row model-row head"><span>提供方 / 模型</span><span>协议 / 基础地址</span><span>接入 / 状态</span><span>操作</span></div>'+(items.length?items.map(p=>`<div class="row model-row"><span><strong>${esc(p.name)}</strong><small>guanyin-${esc(p.code)}</small><small>${p.config.models.map(m=>esc(m.id)).join(' · ')}</small></span><span>${esc(p.config.api)}<small>${esc(p.config.baseURL)}</small></span><span>${p.spaceCount} 个空间<small>${p.enabled?'已启用':'已停用'} · 密钥不回显</small></span><span class="row-actions"><button class="model-edit" data-id="${p.id}">编辑</button><button class="model-spaces" data-id="${p.id}">接入情况</button><button class="model-delete danger" data-id="${p.id}">删除</button></span></div>`).join(''):'<div class="empty compact">尚未登记模型提供方。</div>');$$('.model-edit').forEach(b=>b.onclick=()=>openModelProvider(b.dataset.id));$$('.model-spaces').forEach(b=>b.onclick=()=>openModelSpaces(b.dataset.id));$$('.model-delete').forEach(b=>b.onclick=()=>openDeleteModel(b.dataset.id))}
function openModelProvider(id){if(me.role!=='platform_admin')return;const p=modelProviders.find(p=>p.id===id),f=$('#model-provider-form');f.reset();f.dataset.id=p?.id||'';$('#model-provider-title').textContent=p?'编辑模型提供方':'新增模型提供方';f.elements.code.readOnly=Boolean(p);f.elements.apiKey.required=!p;f.elements.apiKey.value='';for(const field of ['name','code'])f.elements[field].value=p?.[field]||'';for(const field of ['api','baseURL','streamIdleTimeoutMs'])f.elements[field].value=p?.config[field]??({api:'openai-completions',baseURL:'',streamIdleTimeoutMs:600000}[field]);f.elements.requestModel.value=p?.config.models?.length===1?p.config.models[0].id:'';f.elements.models.value=JSON.stringify(p?.config.models?.map(({id,name,...options})=>({...options,...(p.config.models.length>1?{id,name}:name!==p.name?{name}:{})}))||[{reasoningEfforts:{off:null,low:'low',medium:'medium',high:'high'}}],null,2);f.elements.compat.value=JSON.stringify(p?.config.compat||{supportsReasoningEffort:true},null,2);f.elements.enabled.checked=p?.enabled??true;f.querySelector('.form-message').textContent='';$('#model-provider-dialog').showModal()}
$('#model-provider-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit]'),m=f.querySelector('.form-message');b.disabled=true;m.textContent='正在保存并同步已接入空间…';try{const value=Object.fromEntries(new FormData(f));value.enabled=f.elements.enabled.checked;value.streamIdleTimeoutMs=Number(value.streamIdleTimeoutMs);const r=await request('/api/admin/model-providers'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PATCH':'POST',body:JSON.stringify(value)});f.elements.apiKey.value='';$('#model-provider-dialog').close();await loadModelProviders();toast(r.sync.some(s=>s.status==='error')?'已保存，部分空间同步失败，可在空间模型管理中重试':r.sync.some(s=>s.status==='pending')?'已保存，部分空间容器未就绪，尚未同步':'提供方已保存')}catch(error){m.textContent=error.message}finally{b.disabled=false}}
async function openModelSpaces(id){const p=modelProviders.find(p=>p.id===id);$('#model-spaces-name').textContent=p?.name||'模型接入情况';$('#model-spaces-list').innerHTML='<div class="loading">正在读取…</div>';$('#model-spaces-dialog').showModal();try{const {spaces}=await request(`/api/admin/model-providers/${id}/spaces`);$('#model-spaces-list').innerHTML=spaces.length?spaces.map(s=>`<div class="mcp-space-row"><span><strong>${esc(s.name)}</strong><small>${esc(modelSyncName[s.syncStatus]||s.syncStatus)}</small></span><span>${esc(statusName[s.status]||s.status)}</span><button class="model-open-space" data-id="${s.id}" data-name="${esc(s.name)}">管理模型</button></div>`).join(''):'<div class="empty compact">尚未接入空间。请在“空间管理 → 管理 → 管理模型”中选择此提供方。</div>';$$('.model-open-space').forEach(b=>b.onclick=()=>{$('#model-spaces-dialog').close();openSpaceModels({id:b.dataset.id,name:b.dataset.name})})}catch(error){$('#model-spaces-list').textContent=error.message}}
async function openSpaceModels(space){if(me.role!=='platform_admin')return;modelSpace=space;$('#space-models-name').textContent=space.name;$('#space-model-providers').innerHTML='<div class="loading">正在读取模型配置…</div>';$('#space-models-form .form-message').textContent='';$('#space-models-form button[type=submit]').disabled=true;$('#space-model-retry').disabled=true;$('#space-models-dialog').showModal();try{const r=await request(`/api/admin/instances/${space.id}/models`);modelProviders=r.providers;modelSpaceConfig=r.config;$('#space-model-providers').innerHTML=r.providers.length?r.providers.map(p=>`<label class="model-binding"><input type="checkbox" value="${p.id}" ${r.config.providerIds.includes(p.id)?'checked':''} ${!p.enabled&&!r.config.providerIds.includes(p.id)?'disabled':''}><span><strong>${esc(p.name)}</strong><small>${esc(p.config.models.map(m=>m.name||m.id).join(' · '))}${p.enabled?'':' · 已停用，可取消接入'}</small></span></label>`).join(''):'<div class="empty compact">请先在模型管理中新增提供方。</div>';$$('#space-model-providers input').forEach(el=>el.onchange=()=>renderDefaultModel());renderDefaultModel(r.config.defaultProviderId&&r.config.defaultModel?JSON.stringify([r.config.defaultProviderId,r.config.defaultModel]):'');renderModelSync();$('#space-models-form button[type=submit]').disabled=false;$('#space-model-retry').disabled=!r.config.revision}catch(error){$('#space-model-providers').textContent=error.message}}
function renderDefaultModel(selected=$('#space-default-model').value){const ids=$$('#space-model-providers input:checked').map(el=>el.value);$('#space-default-model').innerHTML='<option value="">不指定平台默认模型</option>'+modelProviders.filter(p=>p.enabled&&ids.includes(p.id)).flatMap(p=>p.config.models.map(m=>`<option value="${esc(JSON.stringify([p.id,m.id]))}">${esc(p.name)} / ${esc(m.name||m.id)}</option>`)).join('');$('#space-default-model').value=[...$('#space-default-model').options].some(o=>o.value===selected)?selected:''}
function modelSyncFeedback(status){return {synced:'模型已同步到 DSH。',pending:'配置已保存，容器尚未就绪，实际尚未同步；容器就绪后将自动同步。',error:'配置已保存，同步失败；后台会自动重试，也可检查空间状态、DSH 镜像与凭证后手动同步。',unmanaged:'尚未配置平台模型，无需同步。'}[status]||'同步状态未确认，请刷新后重试。'}
function renderModelSync(){$('#space-model-sync-status').textContent=modelSyncName[modelSpaceConfig.syncStatus]||modelSpaceConfig.syncStatus}
$('#space-models-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]'),m=e.target.querySelector('.form-message');b.disabled=true;$('#space-model-retry').disabled=true;m.textContent='正在保存并同步…';const chosen=$('#space-default-model').value,selection=chosen?JSON.parse(chosen):[];try{const r=await request(`/api/admin/instances/${modelSpace.id}/models`,{method:'PUT',body:JSON.stringify({providerIds:$$('#space-model-providers input:checked').map(el=>el.value),defaultProviderId:selection[0]||null,defaultModel:selection[1]||null,revision:modelSpaceConfig.revision})});modelSpaceConfig=r.config;renderModelSync();m.textContent=modelSyncFeedback(r.sync.status);toast(r.sync.status==='synced'?'模型已同步到空间':'配置已保存，详见同步状态')}catch(error){m.textContent=error.message}finally{b.disabled=false;$('#space-model-retry').disabled=false}}
$('#space-model-retry').onclick=async()=>{const b=$('#space-model-retry'),m=$('#space-models-form .form-message');b.disabled=true;m.textContent='正在同步…';try{const r=await request(`/api/admin/instances/${modelSpace.id}/models/sync`,{method:'POST'});modelSpaceConfig=r.config;renderModelSync();m.textContent=modelSyncFeedback(r.sync.status)}catch(error){$('#space-models-form .form-message').textContent=error.message}finally{b.disabled=false}}
