let modelStatusRefreshing=false;
setInterval(async()=>{
  const dialog=$('#space-models-dialog'),retry=$('#space-model-retry'),spaceId=modelSpace?.id;
  if(!dialog.open||!spaceId||retry.disabled||modelStatusRefreshing)return;
  modelStatusRefreshing=true;
  try{
    const {config}=await request(`/api/admin/instances/${spaceId}/models`);
    if(dialog.open&&!retry.disabled&&modelSpace?.id===spaceId&&config.revision===modelSpaceConfig.revision){
      const changed=config.syncStatus!==modelSpaceConfig.syncStatus;
      modelSpaceConfig=config;renderModelSync();
      if(changed)$('#space-models-form .form-message').textContent=modelSyncFeedback(config.syncStatus);
    }
  }catch{}finally{modelStatusRefreshing=false}
},15_000);
